@startuml

class Customer {
  + Name : string
  + Surname : string
  + Email : string
  + Telephone : string
  + HomeAddress : string
}

class Order {
  + TotalCost : double
  + EstimatedDeliveryTime : time
  + Status : string
}

class Dish {
  + Name : string
  + PreparationTime : int
}

class OrderLine {
  + Quantity : int
}

class Payment {
  + PaymentMethod : string
  + IsSuccessful : boolean
}

Customer "1" -- "*" Order : places
Order "1" *-- "1..*" OrderLine
OrderLine "*" -- "1" Dish
Order "1" -- "0..1" Payment : paid by

@enduml

